#!/usr/bin/env bun
/**
 * End-to-end smoke script: verifies that CLI generated by `trunkPortCli` for
 * IOS XE multilayer switches (3650-24PS, IE-3400) is accepted by PT 9's parser.
 *
 * Manual script (not executed in CI). Start it while Packet Tracer 9 is open
 * and connected via the Student MCP Bridge.
 */

import { Bridge } from "../src/bridge/http-bridge.js";
import {
  addDeviceJs,
  bulkCliJs,
  removeDeviceJs,
} from "../src/ipc/generator.js";
import { waitForCliReady } from "../src/ipc/cli-wait.js";
import { trunkPortCli, wrapInConfig } from "../src/recipes/switching/cli.js";
import { runShowRunning } from "../src/sim/runner.js";

const PORT = 54321;

interface MultilayerCase {
  readonly ptType: string;
  readonly port: string;
  readonly allowed: readonly number[];
  readonly native: number;
}

const CASES: readonly MultilayerCase[] = [
  // 3650-24PS (IOS XE 16.x)
  { ptType: "3650-24PS", port: "GigabitEthernet1/0/24", allowed: [10, 20, 30], native: 99 },
  // IE-3400 (IOS XE 17.x)
  { ptType: "IE-3400",   port: "GigabitEthernet1/1",    allowed: [10, 20, 30], native: 99 },
];

interface CaseResult {
  readonly ptType: string;
  readonly ok: boolean;
  readonly note: string;
}

async function waitBootstrap(bridge: Bridge): Promise<boolean> {
  const deadline = Date.now() + 60_000;
  while (Date.now() < deadline) {
    if (bridge.status().connected) return true;
    await new Promise((r) => setTimeout(r, 250));
  }
  return false;
}

async function smokeOne(bridge: Bridge, c: MultilayerCase): Promise<CaseResult> {
  const dev = `__SMK_${c.ptType.replace(/[^A-Z0-9]/gi, "_")}`;
  try {
    await bridge.sendAndWait(
      addDeviceJs({
        name: dev,
        category: "multilayerswitch",
        model: c.ptType,
        x: 200,
        y: 200,
      }),
      { timeoutMs: 20_000, label: `add ${dev}` },
    );
    await waitForCliReady(bridge, dev, 90_000);

    // Emit the exact production recipe CLI (with encapsulation="dot1q") to verify
    // the filter removes unsupported encapsulation lines for these models.
    const trunkBody = trunkPortCli({
      switch: dev,
      switchModel: c.ptType,
      port: c.port,
      encapsulation: "dot1q",
      allowed: c.allowed,
      native: c.native,
    });

    if (/switchport trunk encapsulation/i.test(trunkBody)) {
      return {
        ptType: c.ptType,
        ok: false,
        note: `trunkPortCli emitted 'switchport trunk encapsulation' for ${c.ptType}`,
      };
    }

    const block = wrapInConfig(trunkBody);
    const reply = await bridge.sendAndWait(
      bulkCliJs(dev, block, 4_000),
      { timeoutMs: 30_000, label: `trunk cli ${dev}` },
    );
    const output = reply ?? "<null>";

    if (/Invalid input detected/i.test(output)) {
      return {
        ptType: c.ptType,
        ok: false,
        note: `CLI parser rejected trunk command:\n${output}`,
      };
    }

    // Wait briefly for running-config to flush after `end`.
    await new Promise((r) => setTimeout(r, 1_500));
    const running = await runShowRunning(bridge, dev, c.port, 8_000);

    const checks = [
      { regex: /switchport mode trunk/i, label: "switchport mode trunk" },
      { regex: new RegExp(`switchport trunk allowed vlan ${c.allowed.join(",")}`, "i"), label: `allowed vlan ${c.allowed.join(",")}` },
      { regex: new RegExp(`switchport trunk native vlan ${c.native}`, "i"), label: `native vlan ${c.native}` },
    ];
    const missing = checks.filter((ch) => !ch.regex.test(running)).map((ch) => ch.label);
    if (missing.length > 0) {
      return {
        ptType: c.ptType,
        ok: false,
        note: `running-config missing: ${missing.join(", ")}\n--- running-config ---\n${running}`,
      };
    }

    return { ptType: c.ptType, ok: true, note: `trunk persisted cleanly on ${c.port}` };
  } catch (e) {
    return { ptType: c.ptType, ok: false, note: `error: ${(e as Error).message}` };
  } finally {
    try {
      await bridge.sendAndWait(removeDeviceJs(dev), { timeoutMs: 5_000, label: `cleanup ${dev}` });
    } catch {
      /* best-effort cleanup */
    }
  }
}

async function main(): Promise<number> {
  const bridge = new Bridge(PORT);
  bridge.start();
  console.log(`[smoke-trunk] bridge listening on :${PORT}; start Student MCP Bridge in PT 9...`);
  if (!(await waitBootstrap(bridge))) {
    bridge.stop();
    console.error("[smoke-trunk] no bridge connection detected");
    return 2;
  }

  const results: CaseResult[] = [];
  for (const c of CASES) {
    process.stdout.write(`[smoke-trunk] ${c.ptType.padEnd(11)} ... `);
    const r = await smokeOne(bridge, c);
    results.push(r);
    process.stdout.write(`${r.ok ? "OK" : "FAIL"}\n`);
    if (!r.ok) {
      console.log(r.note.split("\n").map((l) => `        ${l}`).join("\n"));
    }
  }

  bridge.stop();

  console.log("\n=== Summary ===");
  for (const r of results) {
    console.log(`  ${r.ptType.padEnd(11)} ${r.ok ? "OK  " : "FAIL"} ${r.note.split("\n")[0]}`);
  }
  const fails = results.filter((r) => !r.ok);
  if (fails.length === 0) {
    console.log(`\n${results.length}/${results.length} multilayer trunks accepted by PT 9.`);
    return 0;
  }
  console.log(`\n${fails.length}/${results.length} failed — inspect trunkPortCli + classRejectsEncapsulation.`);
  return 1;
}

main().then((code) => process.exit(code), (err) => {
  console.error("[smoke-trunk] fatal", err);
  process.exit(1);
});
